    return [m.content ?? "", ...(m.tool_calls ?? []).map((t) => `[tool call ${t.function.name}] ${t.function.arguments}`)]
      .filter(Boolean)
      .join("\n");
  return m.content;
}

export async function chat(opts: {
  agent: string;
  system: string;
  messages: ChatMessage[];
  tools?: ToolDef[];
  effort?: "low" | "medium" | "high";
  model?: string;
  maxTokens?: number;
}): Promise<ChatResult> {
  const model = opts.model ?? config.model;
  if (!config.openrouterApiKey) throw new Error("OPENROUTER_API_KEY is not set (see .env.example)");

  const spent = inferenceSpentCents();
  if (spent >= config.llmBudgetCents) {
    throw new Error(
      `LLM budget reached: ~$${(spent / 100).toFixed(2)} spent of $${(config.llmBudgetCents / 100).toFixed(2)} (LLM_BUDGET_CENTS)`
    );
  }

  // Per-run token budget: estimate the prompt conservatively (~3 chars/token)
  // and cap the reply so the call can't overshoot what this agent has left.
  return withSpan(`llm:${opts.agent}`, { agent: opts.agent, model }, async (span) => {
    const res = await fetch(`${config.openrouterBaseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${config.openrouterApiKey}`,
        "Content-Type": "application/json",
        "X-Title": "AutoShelf",
      },
      body: JSON.stringify({
        model,
        max_tokens: maxTokens,
        messages: [{ role: "system", content: opts.system }, ...opts.messages],
        ...(opts.tools?.length
          ? {
              tools: opts.tools.map((t) => ({
                type: "function",
                function: { name: t.name, description: t.description, parameters: t.input_schema },
              })),
            }
          : {}),
        reasoning: { effort: opts.effort ?? "medium" },

  let lastText = "";
  for (let turn = 0; turn < MAX_TURNS; turn++) {
    let res;
    try {
      res = await chat({
        agent: spec.agent,
        system: spec.system,
        messages,
        tools: spec.tools,
        effort: spec.effort,
      });
    } catch (err) {
      if (!(err instanceof TokenBudgetExceeded)) throw err;
      // Out of tokens for this run: stop cleanly and hand back what we have.
      const note = `Stopped early: ${err.message}.`;
      steps.write({ kind: "text", content: note });
      return lastText ? `${lastText}\n\n${note}` : note;
    }
    if (res.text) lastText = res.text;
    addCost(res.costCents);
    recordLlmCost(spec.agent, ctx, res.model, res.inTokens, res.outTokens, res.costCents);

    if (res.reasoning) steps.write({ kind: "thinking", content: res.reasoning });
    if (res.text) steps.write({ kind: "text", content: res.text });
    messages.push(res.message);

    if (res.toolUses.length === 0) return res.text;

    for (const use of res.toolUses) {
      const { text, isError } = await execTool(toolsByName.get(use.name), use.name, use.input, ctx, steps);
      messages.push({ role: "tool", tool_call_id: use.id, content: isError ? `ERROR: ${text}` : text });
    }
  }
  return "Stopped: hit the turn limit.";
}

async function mockLoop(
  spec: AgentSpec,
  task: string,
  ctx: AgentCtx,
  steps: StepWriter,
  toolsByName: Map<string, AgentTool>
): Promise<string> {
  const history: MockHistory = [];
  for (let turn = 0; turn < MAX_TURNS; turn++) {
    const step = spec.mock(history, task);
    steps.write({ kind: "thinking", content: step.thinking });
    if (!step.calls?.length) {
      const answer = step.answer ?? "Done.";
      steps.write({ kind: "text", content: answer });
      return answer;
    }
    for (const call of step.calls) {
      const { text, isError } = await execTool(toolsByName.get(call.name), call.name, call.input, ctx, steps);
      let result: unknown = text;
      try {
        result = JSON.parse(text);
      } catch {
        // plain-text result
      }
      history.push({ name: call.name, input: call.input, result: isError ? { error: text } : result });
    }
  }
  return "Stopped: hit the turn limit.";
}

