/** Expected cost of the next model turn: each turn re-sends the history, so add the last growth step. */
export function projectNextTurn(turnCosts: number[]): number {
  const last = turnCosts.at(-1);
  if (last === undefined) return 0;
  const prev = turnCosts.at(-2) ?? last;
  return last + Math.max(0, last - prev);
}

/** "final" when what's left covers this turn but not the one after, so the agent must wrap up now. */
export function planTurn(left: number, turnCosts: number[]): "normal" | "final" {
  const next = projectNextTurn(turnCosts);
  if (next === 0) return "normal";
  return left < 2 * next ? "final" : "normal";
}
